import SwiftUI

struct Lesson: Identifiable, Hashable { let id: UUID; let title: String }

struct LessonNavigationView: View {
    let lessons: [Lesson]
    var body: some View {
        NavigationStack {
            List(lessons) { lesson in
                NavigationLink(value: lesson) { Label(lesson.title, systemImage: "book") }
            }
            .navigationTitle("Lektionen")
            .navigationDestination(for: Lesson.self) { lesson in
                LessonDetailView(lesson: lesson)
            }
        }
    }
}

import SwiftUI

struct LessonSheetView: View {
    let lessons: [Lesson]
    @State private var selectedLesson: Lesson?

    var body: some View {
        List(lessons) { lesson in
            Button(lesson.title) { selectedLesson = lesson }
        }
        .sheet(item: $selectedLesson) { lesson in
            NavigationStack {
                LessonDetailView(lesson: lesson)
                    .toolbar {
                        ToolbarItem(placement: .confirmationAction) {
                            Button("Fertig") { selectedLesson = nil }
                        }
                    }
            }
        }
    }
}

import SwiftUI

struct GameMode: Identifiable { let id: String; let title: String }

struct GameLauncher: View {
    @State private var activeGame: GameMode?
    var body: some View {
        Button("Spiel starten") { activeGame = GameMode(id: "story", title: "Story") }
            .fullScreenCover(item: $activeGame) { mode in GameScreen(mode: mode) }
    }
}

struct GameScreen: View {
    @Environment(\.dismiss) private var dismiss
    let mode: GameMode
    var body: some View {
        ZStack(alignment: .topLeading) {
            Color.black.ignoresSafeArea()
            Button("Beenden", systemImage: "xmark") { dismiss() }.padding()
            Text(mode.title).font(.largeTitle.bold()).frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .foregroundStyle(.white)
    }
}
